<?php
require_once 'includes/config.php'; require_admin();
$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{
 if(($_POST['action']??'')==='review'){ $id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'');$remark=trim((string)($_POST['admin_remark']??''));if(!in_array($status,['approved','rejected'],true)||$remark==='')throw new RuntimeException('Choose approve/reject and provide an administrator remark.');$q=$dbh->prepare("UPDATE srms_teacher_leaves SET status=:s,admin_remark=:r,reviewed_by=:a,reviewed_at=NOW(),updated_at=NOW() WHERE id=:id AND status='pending'");$q->execute([':s'=>$status,':r'=>$remark,':a'=>$_SESSION['admin_id'],':id'=>$id]);if(!$q->rowCount())throw new RuntimeException('This request is no longer pending. Refresh the page.');audit_log($dbh,'TEACHER_LEAVE_REVIEW','Leave #'.$id.' '.$status.' by '.($_SESSION['alogin']??'admin'));$message='Leave request '.$status.'.';
 }
}catch(Throwable $e){$error=$e instanceof PDOException?'Leave tables are unavailable; apply Phase 14 migration.':$e->getMessage();}}
$teacherId=(int)($_GET['teacher_id']??0);$balanceYear=(int)($_GET['year']??date('Y'));if($balanceYear<2000||$balanceYear>2100)$balanceYear=(int)date('Y');$statusFilter=(string)($_GET['status']??'');$teachers=$dbh->query('SELECT id,username,full_name FROM teachers ORDER BY full_name')->fetchAll();
$sql="SELECT l.*,t.full_name,t.username,lt.leave_name,a.UserName reviewer FROM srms_teacher_leaves l JOIN teachers t ON t.id=l.teacher_id JOIN srms_leave_types lt ON lt.id=l.leave_type_id LEFT JOIN admin a ON a.id=l.reviewed_by WHERE 1=1";$args=[];if($teacherId){$sql.=' AND l.teacher_id=:tid';$args[':tid']=$teacherId;}if(in_array($statusFilter,['pending','approved','rejected','cancelled'],true)){$sql.=' AND l.status=:st';$args[':st']=$statusFilter;}$sql.=' ORDER BY CASE l.status WHEN "pending" THEN 0 ELSE 1 END,l.created_at DESC';$q=$dbh->prepare($sql);$q->execute($args);$leaves=$q->fetchAll();
if(isset($_GET['export'])&&in_array($_GET['export'],['csv','excel'],true)){ $excel=$_GET['export']==='excel';header('Content-Type: '.($excel?'application/vnd.ms-excel':'text/csv').'; charset=utf-8');header('Content-Disposition: attachment; filename="teacher-leave-report-'.date('Y-m-d').($excel?'.xls':'.csv').'"');$out=fopen('php://output','w');$delimiter=$excel?"\t":',';fputcsv($out,['Teacher','Username','Leave Type','Start Date','End Date','Days','Status','Teacher Remark','Admin Remark','Reviewed By','Submitted'],$delimiter);foreach($leaves as $l)fputcsv($out,[$l['full_name'],$l['username'],$l['leave_name'],$l['start_date'],$l['end_date'],$l['days_requested'],$l['status'],$l['teacher_remark'],$l['admin_remark'],$l['reviewer'],$l['created_at']],$delimiter);fclose($out);exit;}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Teacher Leave Management</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-responsive.css"><style>@media print{.no-print,form,nav{display:none!important}.panel{border:0}}</style></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><main class="main-page"><div class="container-fluid srms-page"><h2>Teacher Leave Management</h2><p>Review requests, add a decision remark, and inspect individual leave history.</p><?php if($message):?><div class="alert alert-success"><?php echo e($message);?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?php echo e($error);?></div><?php endif;?>
<div class="panel panel-default"><div class="panel-body no-print"><form method="get" class="form-inline"><label>Teacher </label> <select name="teacher_id" class="form-control"><option value="0">All teachers</option><?php foreach($teachers as $t):?><option value="<?php echo (int)$t['id'];?>" <?php echo $teacherId===(int)$t['id']?'selected':'';?>><?php echo e($t['full_name'].' ('.$t['username'].')');?></option><?php endforeach;?></select> <label>Balance year </label> <select name="year" class="form-control"><?php for($yy=(int)date('Y')+1;$yy>=(int)date('Y')-5;$yy--):?><option value="<?php echo $yy;?>" <?php echo $balanceYear===$yy?'selected':'';?>><?php echo $yy;?></option><?php endfor;?></select> <label>Status </label> <select name="status" class="form-control"><option value="">All statuses</option><?php foreach(['pending','approved','rejected','cancelled'] as $st):?><option <?php echo $statusFilter===$st?'selected':'';?> value="<?php echo $st;?>"><?php echo ucfirst($st);?></option><?php endforeach;?></select> <button class="btn btn-primary">Filter</button> <a class="btn btn-success" href="?teacher_id=<?php echo $teacherId;?>&status=<?php echo e($statusFilter);?>&year=<?php echo $balanceYear;?>&export=csv">Export CSV</a> <a class="btn btn-info" href="?teacher_id=<?php echo $teacherId;?>&status=<?php echo e($statusFilter);?>&year=<?php echo $balanceYear;?>&export=excel">Export Excel</a> <button type="button" onclick="window.print()" class="btn btn-default">Print / Save PDF</button> <a class="btn btn-default" href="teacher-leave-settings.php">Leave types & annual days</a></form></div></div>
<?php if($teacherId):?><div class="panel panel-info"><div class="panel-heading">Individual teacher leave summary · <?php echo $balanceYear;?></div><div class="panel-body"><div class="table-responsive"><table class="table table-bordered"><tr><th>Leave type</th><th>Annual total</th><th>Approved / taken</th><th>Balance</th></tr><?php $types=$dbh->query('SELECT id,leave_name,annual_days FROM srms_leave_types WHERE is_active=1 ORDER BY leave_name')->fetchAll();foreach($types as $t){$q=$dbh->prepare("SELECT COALESCE(SUM(days_requested),0) FROM srms_teacher_leaves WHERE teacher_id=:tid AND leave_type_id=:lid AND status='approved' AND YEAR(start_date)=:yr");$q->execute([':tid'=>$teacherId,':lid'=>$t['id'],':yr'=>$balanceYear]);$taken=(float)$q->fetchColumn();?><tr><td><?php echo e($t['leave_name']);?></td><td><?php echo e($t['annual_days']);?></td><td><?php echo $taken;?></td><td><?php echo max(0,(float)$t['annual_days']-$taken);?></td></tr><?php }?></table></div></div></div><?php endif;?>
<div class="panel panel-primary"><div class="panel-heading">Requests and history</div><div class="panel-body"><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Teacher</th><th>Leave</th><th>Dates / days</th><th>Status</th><th>Teacher remark</th><th>Decision / remark</th><th class="no-print">Review</th></tr></thead><tbody><?php foreach($leaves as $l):?><tr><td><?php echo e($l['full_name']);?><br><small><?php echo e($l['username']);?></small></td><td><?php echo e($l['leave_name']);?></td><td><?php echo e($l['start_date'].' – '.$l['end_date']);?><br><?php echo e($l['days_requested']);?> day(s)</td><td><?php echo e(ucfirst($l['status']));?></td><td><?php echo e($l['teacher_remark']);?></td><td><?php echo e($l['admin_remark']??'—');?><br><small><?php echo e($l['reviewer']??'');?></small></td><td class="no-print"><?php if($l['status']==='pending'):?><form method="post"><input type="hidden" name="csrf_token" value="<?php echo e(csrf_token());?>"><input type="hidden" name="action" value="review"><input type="hidden" name="id" value="<?php echo (int)$l['id'];?>"><textarea name="admin_remark" class="form-control" rows="2" required placeholder="Decision remark"></textarea><select name="status" class="form-control" required><option value="">Decision</option><option value="approved">Approve</option><option value="rejected">Reject</option></select><button class="btn btn-primary btn-xs">Save decision</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?><?php if(!$leaves):?><tr><td colspan="7">No leave records match this filter.</td></tr><?php endif;?></tbody></table></div></div></div></div></main></div></div></div></body></html>